// Generates src/buddy/zoneSources.ts (Metro needs literal require paths) from assets/buddy/manifest.json `zones`.
// Run after `render_buddy.py -- --zones`: node scripts/genBuddyZoneSources.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const manifest = JSON.parse(readFileSync('assets/buddy/manifest.json', 'utf8'));
const req = (rel) => `require('../../assets/buddy/${rel}')`;
const lines = [
  '// GENERATED by scripts/genBuddyZoneSources.mjs from assets/buddy/manifest.json. Do not edit by hand.',
  "import type { ZoneUnit } from './zoneTypes';",
  '',
  'export const ZONE_UNITS: Record<string, ZoneUnit> = {',
];
for (const [name, u] of Object.entries(manifest.zones.units)) {
  lines.push(`  '${name}': {`, `    base: '${u.base}',`, '    masks: {');
  for (const [zone, rel] of Object.entries(u.masks)) lines.push(`      ${zone}: ${req(rel)},`);
  lines.push('    },');
  lines.push(`    shade: ${u.shade ? req(u.shade) : 'undefined'},`);
  if (u.detail) lines.push(`    detail: ${req(u.detail)},`);
  lines.push('  },');
}
lines.push('};', '');
writeFileSync('src/buddy/zoneSources.ts', lines.join('\n'));
console.log('units', Object.keys(manifest.zones.units).length);
